import java.util.HashMap;
import java.util.Map;
import java.util.function.Function;

final class Parsers {
    private final Map<Class<?>, Function<String, ?>> byType = new HashMap<>();

    <T> void register(Class<T> type, Function<String, ? extends T> parser) {
        byType.put(type, parser);
    }

    // T is erased in here, so the caller hands over the Class
    <T> T parse(String text, Class<T> type) {
        Function<String, ?> parser = byType.get(type);
        if (parser == null) throw new IllegalArgumentException("no parser for " + type.getSimpleName());
        return type.cast(parser.apply(text));      // a checked cast: no warning
    }
}

// call site: Money m = parsers.parse("12.50 EUR", Money.class);

kotlin.src:
class Parsers {
    private val byType = HashMap<Class<*>, (String) -> Any>()

    fun <T : Any> register(type: Class<T>, parser: (String) -> T) {
        byType[type] = parser
    }

    // the same Class-token core, callable from Java
    fun <T : Any> parse(text: String, type: Class<T>): T {
        val parser = byType[type] ?: throw IllegalArgumentException("no parser for " + type.simpleName)
        return type.cast(parser(text))
    }

    // the Kotlin wrapper: the compiler writes Money::class.java into each call site
    inline fun <reified T : Any> parse(text: String): T = parse(text, T::class.java)
}

// call site: val m = parsers.parse<Money>("12.50 EUR")

