inline fun <reified T> Any?.asOrNull(): T? = this as? T     // without reified: an unchecked cast that never fails

inline fun <reified T> instancesOf(items: Iterable<*>): List<T> {
    val out = ArrayList<T>()
    for (item in items) if (item is T) out += item           // without reified: Cannot check for instance of erased type 'T'
    return out
}

