static <T> T asOrNull(Object x, Class<T> type) {
    return type.isInstance(x) ? type.cast(x) : null;      // the token does the run-time check
}

static <T> List<T> instancesOf(Iterable<?> items, Class<T> type) {
    List<T> out = new ArrayList<>();
    for (Object item : items) if (type.isInstance(item)) out.add(type.cast(item));
    return out;
}
